INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'İslamiyet öncesi Türk devletlerinde hükümdara yönetme yetkisinin Tanrı tarafından verildiğine inanılan anlayışa ne ad verilir?', 1, 'Kut Anlayışı', 'Töre', 'Kurultay', 'Yarlıg', 'Veraset', 'a', 1, 'Kut, Gök Tanrı tarafından hükümdara ve onun hanedanına verilen yönetme yetkisidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Türk tarihinde ilk kez düzenli ordu teşkilatını (onluk sistem) kuran Türk hükümdarı kimdir?', 1, 'Mete Han', 'Teoman', 'Bumin Kağan', 'Bilge Kağan', 'Atilla', 'a', 1, 'MÖ 209 yılında Asya Hun İmparatoru Mete Han onluk ordu sistemini kurmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'İslamiyet öncesi Türk devletlerinde ölen kişinin ardından düzenlenen cenaze törenine ne ad verilir?', 1, 'Yuğ', 'Balbal', 'Kurgan', 'Uçmağ', 'Tamu', 'a', 1, 'Yuğ törenlerinde ölenin ardından sagu (ağıt) yakılırdı.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Türk tarihinde kendi adına para bastıran ilk Türk hükümdarı ve devleti aşağıdakilerden hangisidir?', 1, 'Baga Tarkan - Türgişler', 'Bumin Kağan - Kök Türkler', 'Mete Han - Asya Hun', 'Kutluk Bilge Kül Kağan - Uygurlar', 'İlteriş Kağan - II. Kök Türk', 'a', 1, 'Türgiş hükümdarı Baga Tarkan adına madeni para (yarmak) bastırmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Türk adıyla kurulan ilk Türk devleti aşağıdakilerden hangisidir?', 1, 'Kök Türk Devleti', 'Asya Hun Devleti', 'Uygur Devleti', 'Avarlar', 'Hazarlar', 'a', 1, 'Bumin Kağan tarafından 552 yılında kurulan I. Kök Türk Devleti, Türk adını resmi olarak kullanan ilk devlettir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Orhun Yazıtları (Göktürk Kitabeleri) hangi hükümdar ve devlet adamları adına dikilmiştir?', 1, 'Bilge Kağan, Kül Tigin, Tonyukuk', 'Bumin Kağan, İstemi Yabgu, Mete Han', 'Mete Han, Teoman, Çiçi', 'Atilla, Bleda, Rua', 'Mukan Kağan, Tapo Kağan, Taspar Kağan', 'a', 1, 'Orhun Abideleri; Vezir Tonyukuk, Kül Tigin ve Bilge Kağan adına dikilmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Yerleşik hayata geçen, tarımla uğraşan ve Maniheizm dinini benimseyen ilk Türk devleti hangisidir?', 1, 'Uygurlar', 'Karluklar', 'Kırgızlar', 'Hazarlar', 'Peçenekler', 'a', 1, 'Bögü Kağan döneminde Maniheizmi kabul eden Uygurlar yerleşik hayata geçen ilk Türk devletidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Museviliği resmi din olarak kabul eden tek Türk devleti aşağıdakilerden hangisidir?', 1, 'Hazarlar', 'Avarlar', 'Macarlar', 'Kıpçaklar', 'Bulgarlar', 'a', 1, 'Kafkaslar ve Karadeniz\'in kuzeyinde hüküm süren Hazarlar Museviliği benimsemiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Bizans ordusunda ücretli askerlik yaparken 1071 Malazgirt Savaşı\'nda Selçuklu tarafına geçen Türk toplulukları hangileridir?', 1, 'Peçenekler ve Uzlar', 'Avarlar ve Bulgarlar', 'Hazarlar ve Türgişler', 'Karluklar ve Yağmalar', 'Kıpçaklar ve Kumanlar', 'a', 1, 'Peçenekler ve Uzlar (Oğuzlar) Malazgirt Savaşı sırasında Büyük Selçuklu ordusuna katılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Dünyanın en uzun destanı kabul edilen Manas Destanı hangi Türk topluluğuna aittir?', 1, 'Kırgızlar', 'Kazaklar', 'Uygurlar', 'Özbekler', 'Türkmenler', 'a', 1, 'Manas Destanı Kırgız Türklerine ait olup yaşayan en uzun destandır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'İslamiyeti kabul eden ilk Türk boyu aşağıdakilerden hangisidir?', 1, 'Karluklar', 'Yağmalar', 'Çiğiller', 'Tuhsiler', 'Oğuzlar', 'a', 1, 'Karluklar, 751 Talas Savaşı sonrası İslamiyeti topluca kabul eden ilk Türk boyudur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Orta Asya\'da kurulan ilk Müslüman Türk devleti aşağıdakilerden hangisidir?', 1, 'Karahanlılar', 'Gazneliler', 'Büyük Selçuklular', 'Tolunoğulları', 'İhşidiler', 'a', 1, 'Satuk Buğra Han döneminde İslamiyeti kabul eden Karahanlılar, Orta Asya\'daki ilk Türk-İslam devletidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Kaşgarlı Mahmut tarafından yazılan ve ilk Türkçe sözlük niteliği taşıyan eser hangisidir?', 1, 'Divânu Lugâti\'t-Türk', 'Kutadgu Bilig', 'Atabetü\'l-Hakayık', 'Divan-ı Hikmet', 'Şehnâme', 'a', 1, 'Divânu Lugâti\'t-Türk, Araplara Türkçeyi öğretmek amacıyla Kaşgarlı Mahmut tarafından yazılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Yusuf Has Hacip tarafından Karahanlı hükümdarı Tabgaç Buğra Han\'a sunulan \'mutluluk veren bilgi\' anlamına gelen siyasetname eseri hangisidir?', 1, 'Kutadgu Bilig', 'Divan-ı Hikmet', 'Atabetü\'l-Hakayık', 'Siyasetnâme', 'Risaletü\'n-Nushiyye', 'a', 1, 'Kutadgu Bilig, Türk-İslam edebiyatının ilk yazılı ve ilk siyasetname niteliğindeki eseridir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Mısır\'da kurulan ilk Türk-İslam devleti aşağıdakilerden hangisidir?', 1, 'Tolunoğulları', 'İhşidiler (Akşitler)', 'Eyyubiler', 'Memlükler', 'Fatımiler', 'a', 1, 'Ahmet bin Tolun tarafından kurulan Tolunoğulları Mısır\'da kurulan ilk Türk devletidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Hicaz bölgesine (Mekke ve Medine) hakim olan ilk Türk devleti aşağıdakilerden hangisidir?', 1, 'İhşidiler (Akşitler)', 'Tolunoğulları', 'Eyyubiler', 'Büyük Selçuklular', 'Osmanlı Devleti', 'a', 1, 'Muhammed bin Toğaç tarafından kurulan İhşidiler Kutsal Topraklara hakim olan ilk Türk devletidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Sultan unvanını kullanan ilk Türk hükümdarı aşağıdakilerden hangisidir?', 1, 'Gazneli Mahmut', 'Alparslan', 'Tuğrul Bey', 'Satuk Buğra Han', 'Melikşah', 'a', 1, 'Gazneli Mahmut, Hindistan seferleri sonrası Abbasi halifesi tarafından Sultan unvanı verilen ilk Türk hükümdarıdır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Anadolu\'nun kapılarını Türklere kesin olarak açan 1071 Malazgirt Savaşı hangi Selçuklu sultanı döneminde kazanılmıştır?', 1, 'Sultan Alparslan', 'Tuğrul Bey', 'Sultan Sencer', 'Melikşah', 'Çağrı Bey', 'a', 1, 'Sultan Alparslan, Bizans İmparatoru Romen Diyojen\'i mağlup ederek Anadolu\'nun fethini başlatmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Anadolu\'da kurulan ilk Türk beyliği aşağıdakilerden hangisidir?', 1, 'Saltuklular', 'Danişmentliler', 'Mengücekliler', 'Artuklular', 'Çaka Beyliği', 'a', 1, 'Erzurum ve çevresinde kurulan Saltuklular, Malazgirt sonrası kurulan ilk Türk beyliğidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 2, 52, '', 'Anadolu\'nun Türk yurdu olduğunu kesinleştiren ve Bizans\'ın Türkleri Anadolu\'dan atma ümidini bitiren savaş hangisidir?', 1, 'Miryokefalon Savaşı (1176)', 'Malazgirt Savaşı (1071)', 'Pasinler Savaşı (1048)', 'Dandanakan Savaşı (1040)', 'Yassıçemen Savaşı (1230)', 'a', 1, 'II. Kılıç Arslan komutasında kazanılan Miryokefalon Savaşı ile Anadolu kesin olarak Türk yurdu olmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Osmanlı Devleti\'nin Rumeli\'de fethettiği ilk toprak ve ilk askeri üs hangisidir?', 1, 'Çimpe Kalesi', 'Edirne', 'Gelibolu', 'Filibe', 'Varna', 'a', 1, 'Orhan Bey döneminde Bizans\'a yapılan yardım karşılığında Çimpe Kalesi üs olarak alınmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Osmanlı Devleti\'nde ilk düzenli ordu olan \'Yaya ve Müsellem\' teşkilatı hangi padişah zamanında kurulmuştur?', 1, 'Orhan Bey', 'Osman Bey', 'I. Murat', 'Yıldırım Bayezid', 'II. Murat', 'a', 1, 'Orhan Gazi döneminde fetihlerin hızlanmasıyla ilk düzenli ordu kurulmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Osmanlı tarihinde ilk kez Haçlı ordusuna karşı kazanılan savaş aşağıdakilerden hangisidir?', 1, 'Sırpsındığı Savaşı (1364)', 'I. Kosova Savaşı', 'Niğbolu Savaşı', 'Varna Savaşı', 'Koyunhisar Savaşı', 'a', 1, 'I. Murat döneminde 1364 yılında yapılan Sırpsındığı Savaşı ilk Osmanlı-Haçlı savaşıdır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Osmanlı Devleti\'nin 1402 Ankara Savaşı sonrası girdiği 11 yıllık taht kavgaları dönemine ne ad verilir?', 1, 'Fetret Devri', 'Lale Devri', 'Duraklama Dönemi', 'Tanzimat Dönemi', 'Meşrutiyet Dönemi', 'a', 1, 'Çelebi Mehmet tahta çıkarak Fetret Devri\'ne son vermiş ve devletin ikinci kurucusu sayılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'İstanbul\'un fethinin dünya tarihi açısından en önemli sonucu aşağıdakilerden hangisidir?', 1, 'Orta Çağ\'ın kapanıp Yeni Çağ\'ın başlaması', 'İpek Yolu\'nun kontrolünün geçmesi', 'Fener Rum Patrikhanesi\'nin himaye edilmesi', 'Topların surları yıkabileceğinin görülmesi', 'Bizans\'ın yıkılması', 'a', 1, 'İstanbul\'un fethi evrensel ölçekte Orta Çağ\'ı bitirip Yeni Çağ\'ı başlatmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Osmanlı Devleti\'nde Halifelik makamı hangi padişahın Mısır Seferi (Mercidabık ve Ridaniye) sonucunda Osmanlı\'ya geçmiştir?', 1, 'Yavuz Sultan Selim', 'Fatih Sultan Mehmet', 'Kanuni Sultan Süleyman', 'II. Bayezid', 'II. Selim', 'a', 1, '1516 Mercidabık ve 1517 Ridaniye Savaşları ile Memlük Devleti yıkılmış ve halifelik Osmanlı\'ya geçmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Akdeniz\'i bir Türk gölü haline getiren 1538 Preveze Deniz Zaferi\'ni kazanan ünlü Osmanlı kaptan-ı deryası kimdir?', 1, 'Barbaros Hayrettin Paşa', 'Piri Reis', 'Turgut Reis', 'Seydi Ali Reis', 'Oruç Reis', 'a', 1, 'Barbaros Hayrettin Paşa, Andrea Doria komutasındaki Haçlı donanmasını Preveze\'de bozguna uğratmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Avusturya Arşidükü\'nün protokolde Osmanlı Sadrazamına denk sayıldığı ve Osmanlı\'nın Avrupa\'da siyasi üstünlük kazandığı antlaşma hangisidir?', 1, '1533 İstanbul (İbrahim Paşa) Antlaşması', '1606 Zitvatorok Antlaşması', '1699 Karlofça Antlaşması', '1718 Pasarofça Antlaşması', '1739 Belgrad Antlaşması', 'a', 1, '1533 İstanbul Antlaşması ile Avusturya kralı Osmanlı sadrazamına denk kabul edilmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Osmanlı Devleti\'nin doğuda en geniş sınırlara ulaştığı antlaşma aşağıdakilerden hangisidir?', 1, '1590 Ferhat Paşa Antlaşması', '1639 Kasr-ı Şirin Antlaşması', '1612 Nasuh Paşa Antlaşması', '1618 Serav Antlaşması', '1555 Amasya Antlaşması', 'a', 1, 'III. Murat döneminde Safevilerle imzalanan Ferhat Paşa Antlaşması doğudaki en geniş sınırlardır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Bugünkü Türkiye-İran sınırının temelini büyük ölçüde belirleyen 1639 tarihli antlaşma hangisidir?', 1, 'Kasr-ı Şirin Antlaşması', 'Ferhat Paşa Antlaşması', 'Amasya Antlaşması', 'Nasuh Paşa Antlaşması', 'Bucaş Antlaşması', 'a', 1, 'IV. Murat\'ın Bağdat Seferi sonrası imzalanan Kasr-ı Şirin Antlaşması bugünkü sınırın temelidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Osmanlı Devleti\'nde padişahtan sonra en yetkili devlet adamı ve padişahın mutlak vekili kimdir?', 1, 'Sadrazam (Vezir-i Azam)', 'Şeyhülislam', 'Kazasker', 'Defterdar', 'Nişancı', 'a', 1, 'Sadrazam padişahın mührünü (mühr-i hümayun) taşır ve padişah adına devleti yönetir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Divan-ı Hümayun\'da adalet ve eğitim işlerine bakan, kadı ve müderrislerin atamasını yapan görevli kimdir?', 1, 'Kazasker', 'Nişancı', 'Defterdar', 'Reisülküttap', 'Şeyhülislam', 'a', 1, 'Kazasker (Kadıasker) adalet ve eğitim teşkilatının başıdır, kadıları ve müderrisleri tayin eder.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Osmanlı Devleti\'nde fethedilen toprakların tahrir defterlerine kaydını yapan ve padişahın tuğrasını çeken divan üyesi kimdir?', 1, 'Nişancı', 'Defterdar', 'Reisülküttap', 'Kaptan-ı Derya', 'Sadrazam', 'a', 1, 'Nişancı iç ve dış yazışmaları yönetir, fermanlara tuğra çeker ve tahrir kayıtlarını tutar.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Osmanlı maliyesinin başında bulunan, gelir ve gider dengesini sağlayan ve bütçeyi hazırlayan divan üyesi kimdir?', 1, 'Defterdar', 'Nişancı', 'Sadrazam', 'Kazasker', 'Reisülküttap', 'a', 1, 'Defterdar devletin mali işlerini ve hazinesini yönetir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Osmanlı Devleti\'nde Kapıkulu Ocaklarına asker yetiştirmek amacıyla gayrimüslim çocukların toplanıp eğitilmesi sistemine ne ad verilir?', 1, 'Devşirme Sistemi', 'Tımar Sistemi', 'İltizam Sistemi', 'Malikane Sistemi', 'Müsadere Sistemi', 'a', 1, 'Devşirme sistemi ile Acemi Ocağı ve Enderun Mektebi\'ne asker ve devlet adamı yetiştirilmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Devlet adamı yetiştirmek üzere Topkapı Sarayı içinde kurulan saray okuluna ne ad verilir?', 1, 'Enderun', 'Birun', 'Harem', 'Medrese', 'Darülfünun', 'a', 1, 'Enderun Mektebi, devşirmelerin üst düzey bürokrat ve yönetici olarak yetiştirildiği saray okuludur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Geliri doğrudan padişah kızlarına ve hanımlarına ayrılan dirlik toprağına ne ad verilir?', 1, 'Paşmaklık', 'Malikane', 'Yurtluk', 'Ocaklık', 'Vakıf', 'a', 1, 'Paşmaklık arazisinin gelirleri saray kadınlarının masraflarına tahsis edilirdi.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Osmanlı Devleti\'nde devletin haksız kazanç sağlayan memurların mallarına el koyma usulüne ne ad verilir?', 1, 'Müsadere', 'İltizam', 'Mukataa', 'Ayanlık', 'Dirlik', 'a', 1, 'Müsadere usulü II. Mahmut döneminde kaldırılmış, Tanzimat Fermanı ile güvence altına alınmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Yeniçerilerin üç ayda bir aldıkları maaşa ne ad verilir?', 1, 'Ulufe', 'Cülus', 'İhsan', 'Dirlik', 'Bahşiş', 'a', 1, 'Yeniçeriler ve Kapıkulu askerleri üç ayda bir ulufe maaşı alırlardı.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 4, 52, '', 'Mimar Sinan\'ın \'Çıraklık, Kalfalık ve Ustalık\' eserleri sırasıyla aşağıdakilerden hangisinde doğru verilmiştir?', 1, 'Şehzade Camii - Süleymaniye Camii - Selimiye Camii', 'Süleymaniye Camii - Selimiye Camii - Şehzade Camii', 'Selimiye Camii - Süleymaniye Camii - Şehzade Camii', 'Sultanahmet Camii - Selimiye Camii - Süleymaniye Camii', 'Fatih Camii - Şehzade Camii - Selimiye Camii', 'a', 1, 'Sinan; Şehzade Camii\'ni çıraklık, Süleymaniye\'yi kalfalık, Edirne Selimiye\'yi ise ustalık eseri olarak nitelendirmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Milli Mücadele\'nin gerekçesi, amacı ve yönteminin ilk kez belirtildiği tarihi belge hangisidir?', 1, 'Amasya Genelgesi', 'Havza Genelgesi', 'Erzurum Kongresi', 'Sivas Kongresi', 'Misakımilli', 'a', 1, '\'Milletin bağımsızlığını yine milletin azim ve kararı kurtaracaktır\' maddesi Amasya Genelgesi\'ndedir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Toplanış amacı bakımından bölgesel ancak aldığı kararlar bakımından ulusal nitelik taşıyan kongre hangisidir?', 1, 'Erzurum Kongresi', 'Sivas Kongresi', 'Amasya Genelgesi', 'Balıkesir Kongresi', 'Alaşehir Kongresi', 'a', 1, 'Erzurum Kongresi Doğu illeri için toplanmış fakat tüm yurdu ilgilendiren kararlar almıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Manda ve himayenin kesin olarak reddedildiği ve tüm cemiyetlerin tek çatı altında birleştirildiği kongre hangisidir?', 1, 'Sivas Kongresi', 'Erzurum Kongresi', 'Havza Genelgesi', 'Afyon Kongresi', 'Pozantı Kongresi', 'a', 1, 'Sivas Kongresi\'nde manda kesin reddedilmiş ve cemiyetler Anadolu ve Rumeli Müdafaa-i Hukuk Cemiyeti adıyla birleştirilmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'İstanbul Hükümeti\'nin Temsil Heyeti\'ni ve Milli Mücadele\'yi hukuken ilk kez tanıdığı gelişme hangisidir?', 1, 'Amasya Görüşmeleri (Protokolü)', 'Bilecik Görüşmeleri', 'Mudanya Mütarekesi', 'Londra Konferansı', 'Gümrü Antlaşması', 'a', 1, 'Salih Paşa ile Mustafa Kemal arasındaki Amasya Görüşmeleri ile Temsil Heyeti hukuken tanınmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'TBMM Hükümeti\'nin uluslararası alanda kazandığı ilk askeri ve siyasi zafer hangi antlaşma ile gerçekleşmiştir?', 1, 'Gümrü Antlaşması', 'Moskova Antlaşması', 'Ankara Antlaşması', 'Kars Antlaşması', 'Lozan Antlaşması', 'a', 1, 'Kazım Karabekir komutasında Ermenilere karşı kazanılan zafer sonrası 1920 Gümrü Antlaşması imzalanmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Düzenli ordunun Batı Cephesi\'nde kazandığı ilk askeri zafer aşağıdakilerden hangisidir?', 1, 'I. İnönü Savaşı', 'II. İnönü Savaşı', 'Sakarya Meydan Muharebesi', 'Büyük Taarruz', 'Kütahya-Eskişehir Savaşı', 'a', 1, 'Albay İsmet İnönü komutasındaki düzenli ordu Yunan ordusunu I. İnönü Savaşı\'nda durdurmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Mustafa Kemal Paşa\'ya \'Gazi\' unvanı ve \'Mareşal\' rütbesi hangi savaştan sonra TBMM tarafından verilmiştir?', 1, 'Sakarya Meydan Muharebesi', 'Büyük Taarruz', 'I. İnönü Savaşı', 'Çanakkale Savaşı', 'Trablusgarp Savaşı', 'a', 1, '22 gün 22 gece süren Sakarya Meydan Muharebesi\'nden sonra Mustafa Kemal\'e Mareşallik ve Gazilik verilmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Türk ordusunun Sakarya Savaşı öncesinde ihtiyaçlarını karşılamak amacıyla yayımlanan milli emirler hangisidir?', 1, 'Tekalif-i Milliye Emirleri', 'Teşkilat-ı Esasiye', 'Hıyanet-i Vataniye', 'Misak-ı İktisadi', 'Takrir-i Sükun', 'a', 1, 'Başkomutan Mustafa Kemal 7-8 Ağustos 1921\'de Tekalif-i Milliye Emirleri\'ni yayımlamıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Milli Mücadele\'nin silahlı dönemini sona erdiren ve Doğu Trakya\'nın savaşsız kurtarılmasını sağlayan mütareke hangisidir?', 1, 'Mudanya Ateşkes Antlaşması', 'Mondros Ateşkes Antlaşması', 'Lozan Barış Antlaşması', 'Gümrü Antlaşması', 'Ankara Antlaşması', 'a', 1, 'İsmet Paşa\'nın temsil ettiği Mudanya Mütarekesi ile İstanbul, Boğazlar ve Doğu Trakya savaşsız alınmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', '24 Temmuz 1923\'te imzalanan Lozan Barış Antlaşması\'nda Türkiye\'yi başdelege olarak temsil eden devlet adamı kimdir?', 1, 'İsmet İnönü', 'Rauf Orbay', 'Kazım Karabekir', 'Fevzi Çakmak', 'Ali Fuat Cebesoy', 'a', 1, 'Dışişleri Bakanı İsmet Paşa (İnönü) Lozan\'da Türk heyetinin başkanlığını yapmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Egemenliğin kayıtsız şartsız millete ait olduğunu savunan ve cumhuriyet rejimini temel alan Atatürk ilkesi hangisidir?', 1, 'Cumhuriyetçilik', 'Milliyetçilik', 'Halkçılık', 'Devletçilik', 'Laiklik', 'a', 1, 'Cumhuriyetçilik; milli egemenlik, seçim, meclis ve çok partili hayatı doğrudan kapsar.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Toplumda hiçbir sınıfa, zümreye veya aileye ayrıcalık tanınmamasını ve kanun önünde eşitliği savunan ilke hangisidir?', 1, 'Halkçılık', 'Devletçilik', 'Milliyetçilik', 'İnkılapçılık', 'Laiklik', 'a', 1, 'Halkçılık ilkesinin temeli sosyal adalet, eşitlik ve ayrıcalıksızlıktır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Özel sektörün yetersiz kaldığı alanlarda büyük yatırımların devlet eliyle yapılmasını öngören ekonomik ilke hangisidir?', 1, 'Devletçilik', 'Cumhuriyetçilik', 'Halkçılık', 'Milliyetçilik', 'Laiklik', 'a', 1, '1930\'lu yıllarda uygulanan 1. Beş Yıllık Sanayi Planı Devletçilik ilkesinin sonucudur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Türk parasını korumak ve milli ticareti geliştirmek amacıyla Kabotaj Kanunu\'nun çıkarılması hangi ilkeyle doğrudan ilişkilidir?', 1, 'Milliyetçilik', 'Devletçilik', 'Halkçılık', 'Laiklik', 'Cumhuriyetçilik', 'a', 1, 'Türk karasularında ticaret ve taşıma hakkının Türk gemicilere verilmesi Milliyetçilik ilkesidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Eğitim ve öğretimin tek çatı altında birleştirilmesini sağlayan Tevhid-i Tedrisat Kanunu hangi tarihte kabul edilmiştir?', 1, '3 Mart 1924', '29 Ekim 1923', '1 Kasım 1922', '17 Şubat 1926', '1 Kasım 1928', 'a', 1, '3 Mart 1924\'te Hilafetin kaldırılmasıyla aynı gün Tevhid-i Tedrisat Kanunu çıkarılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Medeni Kanun\'un kabul edilmesiyle (17 Şubat 1926) Türk kadınına aşağıdaki haklardan hangisi VERİLMEMİŞTİR?', 1, 'Seçme ve Seçilme Hakkı', 'Miras Eşitliği', 'Mahkemede Tanıklık Eşitliği', 'Boşanma Hakkı', 'İstediği Mesleğe Girme Hakkı', 'a', 1, 'Kadınlara siyasi haklar (seçme-seçilme) 1930 (Belediye), 1933 (Muhtar) ve 1934\'te (Milletvekili) verilmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Türkiye Cumhuriyeti\'nin ilk muhalefet partisi aşağıdakilerden hangisidir?', 1, 'Terakkiperver Cumhuriyet Fırkası', 'Serbest Cumhuriyet Fırkası', 'Demokrat Parti', 'Milli Kalkınma Partisi', 'Halk Fırkası', 'a', 1, '1924 yılında Kazım Karabekir, Rauf Orbay ve Ali Fuat Cebesoy tarafından kurulmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', '1925 yılında çıkarılan ve Şeyh Sait İsyanı sonrası huzur ve güvenliği sağlamayı amaçlayan kanun hangisidir?', 1, 'Takrir-i Sükun Kanunu', 'Hıyanet-i Vataniye Kanunu', 'Firariler Kanunu', 'Men-i Müskirat Kanunu', 'Teşvik-i Sanayi Kanunu', 'a', 1, 'İsmet İnönü hükümeti döneminde çıkarılan Takrir-i Sükun Kanunu ile inkılaplar güvenceye alınmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Boğazlar Komisyonu\'nun kaldırılarak Boğazların yönetiminin ve güvenliğinin tamamen Türkiye\'ye bırakıldığı sözleşme hangisidir?', 1, '1936 Montrö Boğazlar Sözleşmesi', '1923 Lozan Boğazlar Sözleşmesi', '1937 Sadabat Paktı', '1934 Balkan Antantı', '1921 Ankara Antlaşması', 'a', 1, 'Montrö Sözleşmesi ile Boğazlar üzerindeki Türk egemenliği tam olarak sağlanmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', 'Mustafa Kemal Atatürk\'ün \'Şahsi meselemdir\' dediği ve 1939\'da anavatana katılan toprak parçası neresidir?', 1, 'Hatay', 'Musul', 'Batum', 'Boğazlar', 'Gökçeada', 'a', 1, 'Atatürk\'ün yoğun diplomatik çabaları sonucu Hatay Cumhuriyeti 1939\'da Türkiye\'ye katılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 8, 52, '', 'Türkiye\'nin matematiksel (mutlak) konum koordinatları aşağıdakilerden hangisinde doğru verilmiştir?', 1, '36° - 42° Kuzey Paralelleri / 26° - 45° Doğu Meridyenleri', '26° - 45° Kuzey Paralelleri / 36° - 42° Doğu Meridyenleri', '30° - 40° Kuzey Paralelleri / 20° - 40° Doğu Meridyenleri', '36° - 42° Güney Paralelleri / 26° - 45° Batı Meridyenleri', '35° - 45° Kuzey Paralelleri / 25° - 45° Doğu Meridyenleri', 'a', 1, 'Türkiye 36-42 Kuzey enlemleri ile 26-45 Doğu boylamları arasında yer alır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 8, 52, '', 'Türkiye\'nin en doğusu ile en batısı arasında kaç dakikalık yerel saat farkı vardır?', 1, '76 Dakika', '60 Dakika', '45 Dakika', '90 Dakika', '100 Dakika', 'a', 1, '(45 - 26 = 19 boylam; 19 x 4 = 76 dakika zaman farkı vardır.)');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 8, 52, '', 'Türkiye\'de güneyden kuzeye doğru gidildikçe aşağıdakilerden hangisi AZALMAZ?', 1, 'Gece ile gündüz arasındaki zaman farkı', 'Güneş ışınlarının geliş açısı', 'Sıcaklık ortalamaları', 'Çizgisel hız', 'Yerçekimi kuvveti', 'a', 1, 'Kutuplara doğru gidildikçe gece-gündüz süre farkı artar, azalmaz.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 8, 52, '', 'Türkiye\'de dağların güney yamaçlarının kuzey yamaçlarına göre daha fazla güneş alması ve ısınması ne ile açıklanır?', 1, 'Bakı Etkisi', 'Boylam Etkisi', 'Yükselti Etkisi', 'Karasallık', 'Rüzgar Yönü', 'a', 1, 'Türkiye Yengeç Dönencesi\'nin kuzeyinde yer aldığı için güney yamaçlar daima bakı durumundadır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 8, 52, '', 'Türkiye\'nin ortak saat olarak kullandığı Iğdır meridyeni kaçıncı saat diliminde yer alır?', 1, '+3. Saat Dilimi (45° Doğu)', '+2. Saat Dilimi (30° Doğu)', '+1. Saat Dilimi (15° Doğu)', '+4. Saat Dilimi (60° Doğu)', '0. Saat Dilimi (Greenwich)', 'a', 1, 'Türkiye tüm yıl boyunca 45° Doğu (Iğdır) boylamının yerel saatini ulusal saat (+3) olarak kullanır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 9, 52, '', 'Türkiye\'de karstik şekillerin (polye, obruk, lapyalar) en yaygın görüldüğü coğrafi bölge hangisidir?', 1, 'Akdeniz Bölgesi (Teke ve Taşeli)', 'Güneydoğu Anadolu', 'İç Anadolu', 'Doğu Anadolu', 'Karadeniz Bölgesi', 'a', 1, 'Kalker (kireçtaşı) arazisinin yaygın olduğu Akdeniz Teke ve Taşeli platolarında karstik şekiller yoğundur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 9, 52, '', 'Bir adanın kıyı oku ile karaya bağlanması sonucu oluşan yeryüzü şekline ne ad verilir (Örn: Kapıdağ Yarımadası)?', 1, 'Tombolo (Saplı Ada)', 'Lagün (Kıyı Set Gölü)', 'Falez (Yalıyar)', 'Delta Ovası', 'Haliç', 'a', 1, 'Kapıdağ ve Sinop İnceburun Türkiye\'nin en bilinen tombolo örnekleridir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 9, 52, '', 'Türkiye\'nin en büyük delta ovası aşağıdakilerden hangisidir?', 1, 'Çukurova (Seyhan ve Ceyhan)', 'Bafra Ovası (Kızılırmak)', 'Çarşamba Ovası (Yeşilırmak)', 'Silifke Ovası (Göksu)', 'Menemen Ovası (Gediz)', 'a', 1, 'Seyhan ve Ceyhan nehirlerinin alüvyonlarıyla oluşan Çukurova en büyük delta ovamızdır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 9, 52, '', 'Volkanik patlama sonucu oluşan krater, kaldera ve maar çukurlarına örnek olarak \'Dünya\'nın Nazar Boncuğu\' olarak bilinen göl hangisidir?', 1, 'Meke Maarı (Gölü)', 'Nemrut Krater Gölü', 'Gölcük Gölü', 'Van Gölü', 'Tuz Gölü', 'a', 1, 'Konya Karapınar\'da yer alan Meke Maarı volkanik gaz patlamasıyla oluşmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 9, 52, '', 'Türkiye\'de buzul aşındırma ve biriktirme şekillerine rastlanabilmesi ne ile açıklanır?', 1, 'Yüksek Dağlık Alanların Bulunması', 'Mutlak Konumunun Kutuplara Yakın Olması', 'Okyanus Kıyısında Yer Alması', 'Karasallık Şiddeti', 'Rüzgar Erozyonu', 'a', 1, 'Türkiye orta kuşaktadır; buzul şekilleri sadece yüksekliği 2500-3000 m üzerindeki dağlarda görülür.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 10, 52, '', 'Türkiye\'de yıllık yağış miktarının en fazla olduğu bölüm aşağıdakilerden hangisidir?', 1, 'Doğu Karadeniz Bölümü (Rize)', 'Batı Akdeniz (Antalya)', 'Yıldız Dağları Bölümü', 'Hakkari Yöresi', 'Güney Marmara', 'a', 1, 'Rize çevresi yıllık 2400 mm\'yi aşan yağış miktarıyla Türkiye\'nin en çok yağış alan yeridir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 10, 52, '', 'Akdeniz ikliminin doğal bitki örtüsü olan makilerin tahrip edilmesiyle ortaya çıkan bodur çalı topluluğuna ne ad verilir?', 1, 'Garig (Frigana)', 'Psödomaki', 'Bozkır (Step)', 'Antropojen Bozkır', 'Tayga', 'a', 1, 'Makilerin tahribiyle garig, Karadeniz ormanlarının tahribiyle psödomaki oluşur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 10, 52, '', 'Türkiye\'de kış mevsiminde Sibirya Termik Yüksek Basıncı etkili olduğunda hava durumu nasıl gerçekleşir?', 1, 'Aşırı Soğuk, Ayaz ve Kar Yağışlı', 'Ilık ve Yağmurlu', 'Sıcak ve Nemli', 'Fırtınalı ve Ilık', 'Sisli ve Ilık', 'a', 1, 'Sibirya yüksek basıncı Türkiye\'ye kışın girdiğinde kuru soğuk ve şiddetli ayaz yapar.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 10, 52, '', 'Yazları sıcak ve kurak, kışları ılık ve yağışlı olan Akdeniz ikliminde en fazla yağış hangi mevsimde düşer?', 1, 'Kış', 'İlkbahar', 'Yaz', 'Sonbahar', 'Yıl boyu eşit', 'a', 1, 'Akdeniz ikliminde cephesel kökenli kış yağışları hakimdir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 10, 52, '', 'İç Anadolu Bölgesi\'nde ilkbaharda ısınan havanın yükselmesiyle oluşan konveksiyonel (kırkikindi) yağışlar en çok hangi ayda görülür?', 1, 'Nisan - Mayıs', 'Temmuz - Ağustos', 'Aralık - Ocak', 'Eylül - Ekim', 'Şubat - Mart', 'a', 1, 'İç kesimlerde ısınmaya bağlı konveksiyonel yağışlar ilkbahar aylarında görülür.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 11, 52, '', 'Türkiye\'de nüfus yoğunluğunun en az olduğu coğrafi bölge aşağıdakilerden hangisidir?', 1, 'Doğu Anadolu Bölgesi', 'İç Anadolu Bölgesi', 'Karadeniz Bölgesi', 'Güneydoğu Anadolu', 'Ege Bölgesi', 'a', 1, 'Yüz ölçümünün çok geniş ve arazinin engebeli, iklimin sert olması sebebiyle Doğu Anadolu en seyrektir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 11, 52, '', 'Cumhuriyet tarihinde ilk genel nüfus sayımı hangi yılda yapılmıştır?', 1, '1927', '1923', '1935', '1940', '1950', 'a', 1, 'Türkiye Cumhuriyeti\'nde ilk modern nüfus sayımı 1927 yılında yapılmıştır (13.6 milyon).');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 12, 52, '', 'Dünya rezervlerinin yaklaşık \%72\'si Türkiye\'de bulunan ve jet yakıtı, cam ve seramikte kullanılan stratejik maden hangisidir?', 1, 'Bor', 'Krom', 'Boksit', 'Bakır', 'Demir', 'a', 1, 'Balıkesir, Kütahya ve Eskişehir yörelerinde yoğunlaşan Bor madeninde Türkiye dünya lideridir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 12, 52, '', 'Türkiye\'de taş kömürü yataklarının bulunması arazimizin hangi jeolojik zamanda oluştuğunun kanıtıdır?', 1, 'I. Jeolojik Zaman (Paleozoik)', 'II. Jeolojik Zaman (Mezozoik)', 'III. Jeolojik Zaman (Tersiyer)', 'IV. Jeolojik Zaman (Kuvaterner)', 'Prekambriyen', 'a', 1, 'Taş kömürü 1. Jeolojik zamanda, linyit ise 3. Jeolojik zamanda oluşmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 12, 52, '', 'Türkiye\'de fındık, incir, kayısı ve kiraz üretiminde dünya birincisi olmamız tarımsal potansiyelimizi gösterir. Malatya hangi ürünle özdeşleşmiştir?', 1, 'Kayısı', 'Fındık', 'İncir', 'Üzüm', 'Elma', 'a', 1, 'Malatya dünya kuru kayısı üretim ve ihracatında açık ara birinci sıradadır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 13, 52, '', 'Yetkili bir makam tarafından konulmuş olan yazılı hukuk kurallarının tamamına ne ad verilir?', 1, 'Mevzu Hukuk', 'Müspet (Pozitif) Hukuk', 'Tabii (İdeal) Hukuk', 'Tarihi Hukuk', 'Örf ve Adet Hukuku', 'a', 1, 'Mevzu Hukuk sadece yetkili makamlarca konulan yazılı kuralları (kanun, yönetmelik vb.) kapsar.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 13, 52, '', 'Hukuk kurallarının yaptırımları (müeyyideleri) arasında aşağıdakilerden hangisi YER ALMAZ?', 1, 'Kınama ve Ayıplama', 'Ceza', 'Cebri İcra', 'Tazminat', 'Hükümsüzlük (İptal)', 'a', 1, 'Kınama ve ayıplama ahlak ve görgü kurallarının yaptırımıdır, maddi devlet gücü taşımaz.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 13, 52, '', 'Medeni Kanun\'a göre fiil ehliyetinin şartları arasında aşağıdakilerden hangisi yer almaz?', 1, 'Ergin (reşit) olmak, ayırt etme gücüne sahip olmak, kısıtlı olmamak', 'Evli olmak', 'Temyiz kudretine sahip olmak', 'Kısıtlı bulunmamak', '18 yaşını doldurmuş olmak', 'b', 1, 'Evli olmak fiil ehliyetinin genel şartı değildir; ayırt etme gücü, erginlik ve kısıtlı olmamak şarttır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 13, 52, '', 'Bir hakkın doğumunda veya kazanılmasında geçerli olan iyi niyet kuralı hangisidir?', 1, 'Subjektif İyi Niyet', 'Objektif İyi Niyet (Dürüstlük)', 'Hakkın Kötüye Kullanılması', 'Kuvvet Kullanma', 'Meşru Müdafaa', 'a', 1, 'Hakların kazanılmasında Subjektif İyi Niyet, kullanılmasında ise Dürüstlük Kuralı (Objektif) geçerlidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 14, 52, '', '1982 Anayasası\'nın değiştirilemez ve değiştirilmesi teklif dahi edilemez maddeleri arasında hangisi YER ALMAZ?', 1, 'TBMM\'nin üye tamsayısının 600 olması', 'Devletin şeklinin Cumhuriyet olması (1. Madde)', 'Cumhuriyetin nitelikleri (Demokratik, laik, sosyal hukuk devleti - 2. Madde)', 'Devletin bütünlüğü, resmi dili Türkçe, bayrağı, marşı ve başkenti (3. Madde)', 'İlk 3 maddenin değiştirilemeyeceği hükmü (4. Madde)', 'a', 1, 'TBMM milletvekili sayısı anayasanın değiştirilemez ilk 4 maddesi kapsamında değildir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 14, 52, '', '1982 Anayasası\'na göre bir siyasi partinin TBMM seçimlerinde milletvekili çıkarabilmesi için ülke genelinde alması gereken seçim barajı yüzde kaçtır?', 1, '\%7', '\%10', '\%5', '\%3', '\%1', 'a', 1, 'Seçim kanununda yapılan son değişiklikle ülke barajı \%7\'ye düşürülmüştür.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 14, 52, '', 'Siyasi partilerin kapatılması davalarına hangi mahkeme bakar ve karara bağlar?', 1, 'Anayasa Mahkemesi', 'Yargıtay', 'Danıştay', 'Uyuşmazlık Mahkemesi', 'Sayıştay', 'a', 1, 'Yargıtay Cumhuriyet Başsavcısı\'nın açtığı davada Anayasa Mahkemesi karar verir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 15, 52, '', '1982 Anayasası\'na göre Türkiye Büyük Millet Meclisi kaç milletvekilinden oluşur?', 1, '600', '550', '450', '500', '650', 'a', 1, '2017 anayasa değişikliği ile milletvekili sayısı 550\'den 600\'e çıkarılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 15, 52, '', 'TBMM genel seçimleri kaç yılda bir Cumhurbaşkanlığı seçimi ile birlikte yapılır?', 1, '5 Yılda Bir', '4 Yılda Bir', '3 Yılda Bir', '6 Yılda Bir', '2 Yılda Bir', 'a', 1, 'Anayasa Madde 77 gereğince TBMM ve Cumhurbaşkanlığı seçimleri 5 yılda bir aynı gün yapılır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 15, 52, '', 'Cumhurbaşkanı seçilme yaşı 2017 değişikliği ile kaça indirilmiştir?', 1, '40 Yaşını doldurmuş olmak', '30 Yaşını doldurmuş olmak', '35 Yaşını doldurmuş olmak', '18 Yaşını doldurmuş olmak', '25 Yaşını doldurmuş olmak', 'a', 1, 'Milletvekili seçilme yaşı 18\'e indirilmiş; Cumhurbaşkanı için 40 yaş ve yükseköğrenim şartı korunmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 15, 52, '', 'Anayasa Mahkemesi kaç üyeden oluşur ve üyelerin görev süresi kaç yıldır?', 1, '15 Üye - 12 Yıl', '17 Üye - 9 Yıl', '12 Üye - 6 Yıl', '15 Üye - 5 Yıl', '21 Üye - 10 Yıl', 'a', 1, 'AYM 15 üyeden oluşur. Üyeler bir kez 12 yıllığına seçilir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 15, 52, '', 'Adli yargı kolunun en üst temyiz mahkemesi aşağıdakilerden hangisidir?', 1, 'Yargıtay', 'Danıştay', 'Anayasa Mahkemesi', 'Sayıştay', 'Uyuşmazlık Mahkemesi', 'a', 1, 'Adli yargının temyiz mercii Yargıtay, idari yargının temyiz mercii Danıştay\'dır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 16, 52, '', 'Türkiye\'de il ve ilçe kurulması, kaldırılması ve adlarının değiştirilmesi ne ile yapılır?', 1, 'Kanun ile', 'Cumhurbaşkanlığı Kararnamesi ile', 'İçişleri Bakanlığı Genelgesi ile', 'Yönetmelik ile', 'İl Genel Meclisi Kararı ile', 'a', 1, 'Anayasa m. 126 gereğince il ve ilçeler ancak kanunla kurulur, kaldırılır veya adları değiştirilir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 16, 52, '', 'İl genel idaresinin başında bulunan ve hem devleti hem de Cumhurbaşkanını ilde temsil eden yetkili kimdir?', 1, 'Vali', 'Kaymakam', 'Büyükşehir Belediye Başkanı', 'İl Emniyet Müdürü', 'Garnizon Komutanı', 'a', 1, 'Vali istisnai memurdur ve ilde Cumhurbaşkanının temsilcisi ve idari yürütme vasıtasıdır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 16, 52, '', 'Köyün tüzel kişiliğini temsil eden ve köy derneği tarafından seçilen köy yöneticisi kimdir?', 1, 'Muhtar', 'Kaymakam', 'İhtiyar Heyeti', 'İmam', 'Köy Katibi', 'a', 1, 'Muhtar köy idaresinin başıdır ve köy tüzel kişiliğini temsil eder.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 17, 52, '', 'Birleşmiş Milletler (BM) Genel Merkezi hangi şehirde yer almaktadır?', 1, 'New York (ABD)', 'Cenevre (İsviçre)', 'Brüksel (Belçika)', 'Paris (Fransa)', 'Viyana (Avusturya)', 'a', 1, 'BM Genel Merkezi New York\'tadır; Cenevre ise Avrupa merkezidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 17, 52, '', 'NATO\'ya (Kuzey Atlantik Antlaşması Örgütü) son katılan üye ülke aşağıdakilerden hangisidir?', 1, 'İsveç', 'Finlandiya', 'Kuzey Makedonya', 'Karadağ', 'Ukrayna', 'a', 1, 'İsveç 2024 yılında NATO\'nun 32. üye ülkesi olmuştur.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (4, 18, 52, '', '\'Ağır\' sözcüğü aşağıdaki cümlelerin hangisinde mecaz anlamda kullanılmıştır?', 1, 'Bu kadar ağır sözleri hiçbirimiz hak etmedik.', 'Ağır çuvalları taşırken beli incinmişti.', 'Kamyon ağır adımlarla yokuşu tırmanıyordu.', 'Gemi ağır bir yükle limandan ayrıldı.', 'Ağır metaller sanayide yoğun kullanılır.', 'a', 1, '\'Ağır söz\' kırıcı, incitici anlamında mecazlaşmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (4, 18, 52, '', 'Aşağıdaki cümlelerin hangisinde \'neden-sonuç (gerekçe)\' ilişkisi vardır?', 1, 'Yoğun kar yağışı nedeniyle köy yolları ulaşıma kapandı.', 'Sınavı kazanmak için gece gündüz durmadan çalışıyor.', 'Yarın erken kalkarsan birlikte yürüyüşe gideriz.', 'Konuyu anlasın diye tahtaya şekil çizdi.', 'Seninle görüşmek üzere Ankara\'ya gideceğim.', 'a', 1, 'Yolların kapanması sonuç, kar yağışı ise gerçekleşmiş nedendir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (4, 18, 52, '', 'Aşağıdaki atasözlerinden hangisi \'tutumlu olma ve birikim yapma\' ile ilgilidir?', 1, 'Ak akçe kara gün içindir.', 'Damlaya damlaya göl olur.', 'Ayağını yorganına göre uzat.', 'Sakla samanı gelir zamanı.', 'Hepsi', 'e', 1, 'Verilen tüm atasözleri tasarruf, tutumluluk ve tedbirli olmakla ilgilidir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (4, 20, 52, '', '\'Genç adam, kütüphanedeki eski kitapları büyük bir dikkatle inceledi.\' cümlesinin öge dizilişi hangisidir?', 1, 'Özne - Belirtili Nesne - Zarf Tümleci - Yüklem', 'Özne - Dolaylı Tümleç - Belirtili Nesne - Yüklem', 'Özne - Zarf Tümleci - Nesne - Yüklem', 'Belirtili Nesne - Özne - Yüklem', 'Özne - Belirtisiz Nesne - Yüklem', 'a', 1, 'İnceledi (Yüklem), Genç adam (Özne), kütüphanedeki eski kitapları (Belirtili Nesne), büyük bir dikkatle (Zarf Tümleci).');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (4, 20, 52, '', 'Aşağıdaki cümlelerin hangisinde bir yazım yanlışı vardır?', 1, 'Bu konuyu Mehmet Bey\'de çok iyi biliyordu.', 'TBMM\'nin açılış törenine katıldık.', 'Tarih 29 Ekim 1923\'ü gösteriyordu.', 'O da bizimle sinemaya gelecek mi?', 'Türk Dil Kurumu Başkanlığına dilekçe verdik.', 'a', 1, '\'Mehmet Bey de\' bağlacı ayrı yazılmalıdır, bitişik yazılamaz.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (4, 20, 52, '', 'Aşağıdaki sözcüklerin hangisinde büyük ünlü uyumu (kalınlık-incelik kuralı) aranmaz?', 1, 'Tek heceli ve yabancı kökenli sözcüklerde', 'Türkçe kökenli türemiş sözcüklerde', 'Birleşik sözcüklerde', 'Üç heceli isimlerde', 'Fiil çekimlerinde', 'a', 1, 'Tek heceli sözcüklerde ve Türkçe kökenli olmayan yabancı sözcüklerde büyük ünlü uyumu aranmaz.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (5, 0, 52, '', 'Ardışık 5 tek sayının toplamı 85 olduğuna göre bu sayıların en büyüğü kaçtır?', 1, '21', '19', '17', '23', '25', 'a', 1, 'Ortanca sayı 85 / 5 = 17\'dir. Sayılar: 13, 15, 17, 19, 21. En büyüğü 21\'dir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (5, 0, 52, '', 'Bir sınıftaki öğrencilerin \%60\'ı erkektir. Sınıfta 12 kız öğrenci olduğuna göre sınıf mevcudu kaçtır?', 1, '30', '25', '40', '35', '50', 'a', 1, 'Kızların oranı \%40\'tır. Sınıf mevcudu x olsun. 0.40 * x = 12 => x = 30.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (5, 0, 52, '', 'Bir babanın yaşı, oğlunun yaşının 4 katıdır. 5 yıl sonra babanın yaşı oğlunun yaşının 3 katı olacağına göre çocuk bugün kaç yaşındadır?', 1, '10', '8', '12', '15', '14', 'a', 1, 'Oğul x, baba 4x. 5 yıl sonra: 4x + 5 = 3(x + 5) => 4x + 5 = 3x + 15 => x = 10.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (5, 0, 52, '', 'Bir araç A kentinden B kentine 60 km/s hızla gidip, 90 km/s hızla geri dönmüştür. Bu aracın gidiş-dönüşteki ortalama hızı saatte kaç km\'dir?', 1, '72', '75', '70', '80', '65', 'a', 1, 'Ortalama hız harmonik ortalamadır: (2 * 60 * 90) / (60 + 90) = 10800 / 150 = 72 km/s.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (5, 0, 52, '', '200 TL maliyetle alınan bir ürün \%30 karla kaç TL\'ye satılır?', 1, '260 TL', '230 TL', '250 TL', '280 TL', '300 TL', 'a', 1, 'Kar: 200 * 0.30 = 60 TL. Satış fiyatı: 200 + 60 = 260 TL.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Türk tarihinde ilk yazılı anıtlar Orhun Abideleri (Göktürk Kitabeleri)\'dir.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. Orhun Yazıtları Türklerin bilinen ilk yazılı kaynaklarıdır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 1, 52, '', 'Uygurlar Türk tarihinde kağıt ve matbaayı kullanan ilk devlettir.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. Uygurlar yerleşik hayata geçerek matbaa ve kağıt kullanmışlardır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 3, 52, '', 'Osmanlı Devleti\'nde ilk altın para Fatih Sultan Mehmet döneminde basılmıştır.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. \'Sultani\' adı verilen ilk altın para Fatih döneminde basılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 5, 52, '', 'Amasya Genelgesi\'nde milli egemenlik ilkesinden ilk kez üstü kapalı olarak bahsedilmiştir.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. \'Milletin bağımsızlığını milletin azim ve kararı kurtaracaktır.\'');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (1, 6, 52, '', '1924 Anayasası kabul edildiğinde devletin dini İslam\'dır maddesi yer almıyordu.', 2, 'Doğru', 'Yanlış', '', '', '', 'b', 1, 'Yanlış! \'Devletin dini İslam\'dır\' maddesi 1928 yılında çıkarılmıştır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 8, 52, '', 'Türkiye\'nin en doğu ucu ile en batı ucu arasında 76 dakikalık zaman farkı bulunur.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. 45 - 26 = 19 meridyen; 19 x 4 = 76 dakika.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 9, 52, '', 'Türkiye\'de aktif volkanik dağlar bulunmaktadır.', 2, 'Doğru', 'Yanlış', '', '', '', 'b', 1, 'Yanlış. Türkiye\'deki volkanik dağlar sönmüş (uyuyan) durumdadır.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (2, 12, 52, '', 'Bor madeni rezervlerinde Türkiye dünya birincisidir.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. Dünya rezervlerinin yaklaşık \%72\'si Türkiye\'dedir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 14, 52, '', '1982 Anayasası\'na göre milletvekili seçilme yaşı 18\'dir.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. 2017 değişikliği ile seçilme yaşı 18\'e indirilmiştir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 15, 52, '', 'Cumhurbaşkanı TBMM tarafından 7 yıllığına seçilir.', 2, 'Doğru', 'Yanlış', '', '', '', 'b', 1, 'Yanlış. Cumhurbaşkanı halk tarafından 5 yıllığına seçilir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (3, 16, 52, '', 'İl ve ilçelerin kurulması veya kaldırılması kanun ile yapılır.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru. Anayasa gereği il ve ilçeler ancak kanunla kurulabilir.');
INSERT INTO tbl_question (category, subcategory, language_id, image, question, question_type, optiona, optionb, optionc, optiond, optione, answer, level, note) VALUES (4, 18, 52, '', '\'Damlaya damlaya göl olur\' atasözü tasarruf ve birikim ile ilgilidir.', 2, 'Doğru', 'Yanlış', '', '', '', 'a', 1, 'Doğru.');
